q={h:(WE[113]+WP[2])@WQ[h] for h in range(4)}
ah={h:(WE[:114]@WK[h]@q[h])/sq for h in range(4)}
offs={h:(WP@WK[h]@q[h])/sq for h in range(4)}
t=np.arange(N)
Fd = np.exp(-2j*np.pi*np.outer(t,t)/N)/np.sqrt(N)
freqsets={}
for h in range(4):
    co=Fd.conj().T@ah[h][:N]; amp=np.abs(co)/np.sqrt(N)
    sel=[k for k in range(1,57) if amp[k]>0.012]
    freqsets[h]=np.array(sel)
    print("h",h,"freqs:",sel, np.round(amp[sel],3))
def makebasis(freqs):
    cols=[np.ones(114)]
    for f in freqs: cols += [np.cos(2*np.pi*f*np.arange(114)/N), np.sin(2*np.pi*f*np.arange(114)/N)]
    return np.stack(cols,axis=1)
Bh={h: makebasis(freqsets[h]) for h in range(4)}
coefA={h: np.linalg.lstsq(Bh[h][:113], ah[h][:113], rcond=None)[0] for h in range(4)}
print("a-fit resid:", [np.abs(Bh[h][:113]@coefA[h]-ah[h][:113]).max().round(4) for h in range(4)])
